const recallPct = n => Number(n).toFixed(2).replace('.', ',') + '%';
const recallRatio = (a,b) => b ? a/b*100 : 0;
const recallBase = recallRatio(RECALL.summary.failed, RECALL.summary.total);
const recallZero = RECALL.staff.filter(p=>p.account!=='CHUA_PC' && p.total>0 && p.recovered===0).sort((a,b)=>b.pending-a.pending||b.total-a.total||a.name.localeCompare(b.name));
const recallRisk = RECALL.staff.filter(p=>p.account!=='CHUA_PC' && p.total>=10 && recallRatio(p.failed,p.total)>recallBase).sort((a,b)=>b.failed/b.total-a.failed/a.total||b.failed-a.failed||a.name.localeCompare(b.name));
const recallTitles = ['MỞ ĐẦU','KẾT QUẢ PTTB','BÁO CÁO KTV','KICKOFF THÁNG 9','CHẤT LƯỢNG DỊCH VỤ','CẢNH BÁO CLDV','KẾT QUẢ THU HỒI','THEO DÕI THU HỒI','QUY TRÌNH GSAFE','KẾ HOẠCH HÀNH ĐỘNG','CẢM ƠN & TRAO ĐỔI'];
function recallToneAttrs(value,max,tone='blue'){
 const colors={blue:[32,102,169],green:[13,132,78],orange:[189,111,22],red:[186,49,74]};
 const rgb=colors[tone]||colors.blue;
 const fraction=max>0?Math.max(0,Math.min(1,Math.abs(value)/max)):0;
 const bg=value===0?'#ffffff':`rgba(${rgb.join(',')},${(.055+.18*fraction).toFixed(3)})`;
 const ink=value===0?'#718395':`rgb(${rgb.join(',')})`;
 return `class="num metric-tone" style="--value-bg:${bg};--value-ink:${ink}"`;
}
function recallMetric(label,value,note,tone,mode){return `<button class="card recall-metric ${tone}" onclick="openRecovery('${mode}')"><span>${label}</span><b>${value}</b><small>${note}</small></button>`}
function recallFrame(index,kind,content){return `<section class="scene ${kind}" data-page="${index}" aria-label="Slide ${index+1}" aria-hidden="true"><div class="topbar">${logo()}<div class="recall-topright"><span class="eyebrow">${recallTitles[index]}</span><span class="tag">--/--</span></div></div><div class="recall-snapshot-status" role="status" title="Dữ liệu trên slide là bản chốt ngày 15/10/2026. Google Sheet có nguồn Data_TH tự cập nhật, nhưng trang này chưa tải trực tiếp dữ liệu từ Sheet."><span class="recall-status-dot" aria-hidden="true"></span><span><b>BẢN CHỐT ${RECALL.snapshot}</b><small>SLIDE CHƯA REALTIME</small></span></div>${content}${footer(index)}</section>`}
function recallSlideOverview(){
 const s=RECALL.summary;
 const teams=[...RECALL.teams].sort((a,b)=>b.recovered/b.total-a.recovered/a.total);
 const max=(field)=>Math.max(...teams.map(t=>t[field]));
 const maxRecovery=Math.max(...teams.map(t=>recallRatio(t.recovered,t.total)));
 const maxFailure=Math.max(...teams.map(t=>recallRatio(t.failed,t.total)));
 const rows=teams.map(t=>`<tr role="button" tabindex="0" aria-label="Xem thu hồi đội ${t.team}" onclick="openRecovery('all','${t.team}')" onkeydown="if(event.key==='Enter')openRecovery('all','${t.team}')"><td>${badge(t.team)}</td><td ${recallToneAttrs(t.total,max('total'))}>${nf(t.total)}</td><td ${recallToneAttrs(t.recovered,max('recovered'),'green')}>${t.recovered}</td><td ${recallToneAttrs(recallRatio(t.recovered,t.total),maxRecovery,'green')}><b>${recallPct(recallRatio(t.recovered,t.total))}</b></td><td ${recallToneAttrs(recallRatio(t.failed,t.total),maxFailure,'red')}>${recallPct(recallRatio(t.failed,t.total))}</td><td ${recallToneAttrs(t.pending,max('pending'),'orange')}>${t.pending}</td><td ${recallToneAttrs(t.wifiRecovered,max('wifiRecovered'),'green')}><div class="recall-wifi-inline"><b>${t.wifiRecovered}</b><small>${(t.wifiRate||'—')}</small></div></td></tr>`).join('');
 return recallFrame(6,'scene-recall',`<div class="recall-head"><h1 class="slide-title">KẾT QUẢ <span>THU HỒI THÁNG 10</span></h1><p>Phân công tạo trong ${RECALL.period} · Đơn vị: thiết bị · ${RECALL.staff.filter(p=>p.account!=='CHUA_PC'&&p.total>0).length} KTV + 5 thiết bị Chưa PC</p></div><div class="recall-kpis">${recallMetric('TỔNG PHÂN CÔNG',nf(s.total),'Toàn báo cáo · gồm 5 Chưa PC','blue','all')}${recallMetric('ĐÃ THU HỒI',nf(s.recovered),recallPct(recallRatio(s.recovered,s.total))+' tổng phân công','green','recovered')}${recallMetric('CHƯA THU HỒI',nf(s.pending),recallPct(recallRatio(s.pending,s.total))+' tổng phân công','orange','pending')}${recallMetric('KHÔNG THÀNH CÔNG',nf(s.failed),recallPct(recallBase)+' tổng phân công','red','failed')}${recallMetric('WIFI 6 + WIFI 7 ĐÃ TH',nf(s.wifiRecovered),s.wifiRate+' theo tab báo cáo','green','wifi')}</div><div class="recall-overview-layout"><div class="card recall-team-panel"><div class="recall-panel-heading"><h2>KẾT QUẢ 5 ĐỘI</h2><button class="recall-link" onclick="openRecovery('teams')">Bảng chi tiết ↗</button></div><p class="recall-caption">Nền đậm theo giá trị trong cùng cột. Chọn đội để xem nhân sự.</p><table class="recall-slide-table recall-overview-table"><colgroup><col style="width:17%"><col style="width:13%"><col style="width:9%"><col style="width:15%"><col style="width:15%"><col style="width:12%"><col style="width:19%"></colgroup><thead><tr><th>Đội</th><th>Phân công</th><th>Đã TH</th><th>Tỷ lệ đã TH</th><th>Không TC</th><th>Chưa TH</th><th title="Đã TH / WiFi 6 + 7 phân công">WiFi 6 + 7</th></tr></thead><tbody>${rows}</tbody></table><div class="recall-team-note"><b>${teams[teams.length-1].team} thấp nhất: ${recallPct(recallRatio(teams[teams.length-1].recovered,teams[teams.length-1].total))}</b> đã TH. <b>ThinhPT còn ${RECALL.teams.find(t=>t.team==='ThinhPT').pending}</b> thiết bị chưa TH. <b>Chưa PC: 5 thiết bị.</b></div></div><div class="card recall-warehouse"><div class="recall-panel-heading"><h2>TIẾN ĐỘ NHẬP KHO</h2></div><div class="recall-warehouse-total"><b>${s.recovered}</b><span>thiết bị đã thu hồi</span></div><div class="recall-stack" aria-label="${s.warehouse} đã nhập kho, ${s.waiting} chưa nhập kho"><i style="width:${s.warehouse/s.recovered*100}%"></i><em style="width:${s.waiting/s.recovered*100}%"></em></div><div class="recall-warehouse-row"><span><i class="recall-dot green"></i>Đã nhập kho</span><b>${s.warehouse}</b></div><div class="recall-warehouse-row"><span><i class="recall-dot orange"></i>Chưa nhập kho</span><b>${s.waiting}</b></div><div class="recall-warehouse-note"><b>${pct(s.waiting/s.recovered*100)}</b> thiết bị đã TH còn chờ nhập kho.<br>LocLV: <b>${RECALL.teams.find(t=>t.team==='LocLV').waiting}</b> · ThinhPT: <b>${RECALL.teams.find(t=>t.team==='ThinhPT').waiting}</b> thiết bị.</div><button class="recall-link recall-wide" onclick="openRecovery('warehouse')">Xem KTV còn chờ nhập kho ↗</button></div></div><p class="recall-source">Nguồn: tab Báo Cáo Thu Hồi SG10 (01–15/10/2026). Đơn vị thiết bị. Đã TH = nhập kho + chờ nhập kho.</p>`);
}
function recallSlidePeople(){
 const zeroRows=recallZero.slice(0,6).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${badge(p.team)}</td><td class="recall-orange">${p.pending}</td><td>${p.failed}</td></tr>`).join('');
 const riskRows=recallRisk.slice(0,6).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${badge(p.team)}</td><td>${p.failed}/${p.total}</td><td class="recall-red"><b>${pct(recallRatio(p.failed,p.total))}</b></td></tr>`).join('');
 return recallFrame(7,'scene-recall-people',`<div class="recall-head"><h1 class="slide-title">NHÂN SỰ <span>CẦN THEO SÁT</span></h1><p>Thu hồi ${RECALL.period} · Theo dõi kết quả từng KTV và rà soát từng ca không thành công</p></div><div class="recall-people-layout"><div class="card recall-people-panel"><div class="recall-people-title"><b class="recall-orange">${recallZero.length}</b><div><h2>KTV CHƯA CÓ KẾT QUẢ THU HỒI</h2><p>Có phân công và đã TH = 0. Tổng ${recallZero.reduce((v,p)=>v+p.pending,0)} chưa TH, ${recallZero.reduce((v,p)=>v+p.failed,0)} không TC.</p></div></div><p class="recall-caption">6 KTV còn nhiều thiết bị chưa TH trong nhóm trên.</p><table class="recall-slide-table recall-zero-table"><colgroup><col style="width:35%"><col style="width:27%"><col style="width:19%"><col style="width:19%"></colgroup><thead><tr><th>KTV</th><th>Đội</th><th>Chưa TH</th><th>Không TC</th></tr></thead><tbody>${zeroRows}</tbody></table><button class="recall-link recall-wide" onclick="openRecovery('zero')">Xem đủ ${recallZero.length} KTV chưa có kết quả ↗</button></div><div class="card recall-people-panel"><div class="recall-people-title"><b class="recall-red">${recallPct(recallBase).replace('%','')}<small>%</small></b><div><h2>KHÔNG THÀNH CÔNG CAO</h2><p>Mức chung SG10. Tỷ lệ = Không TC / Tổng phân công.</p></div></div><p class="recall-caption">6 tỷ lệ cao nhất trên mẫu từ 10 thiết bị. Không TC / phân công.</p><table class="recall-slide-table recall-risk-table"><colgroup><col style="width:31%"><col style="width:25%"><col style="width:24%"><col style="width:20%"></colgroup><thead><tr><th>KTV</th><th>Đội</th><th>Không TC / PC</th><th>Tỷ lệ</th></tr></thead><tbody>${riskRows}</tbody></table><button class="recall-link recall-wide" onclick="openRecovery('risk')">Xem nhóm trên mức chung SG10 ↗</button></div></div><div class="recall-action"><b>TRỌNG TÂM</b><span>Đội trưởng rà soát lịch tiếp cận, bổ sung lý do từng ca không thành công và hỗ trợ KTV còn nhiều thiết bị chưa TH.</span><button onclick="openRecovery('pending')">${RECALL.pendingCount} KTV còn tồn ↗</button></div><p class="recall-source">Nguồn: Báo Cáo Thu Hồi A5:AC96. Loại nhân sự không có phân công. Mẫu nhỏ được ghi chú trong bảng chi tiết.</p>`);
}

