// One search box per detail view. Headers retain sorting, with no column filters.
table=function(headers,rows){
 let widths=[];
 if(headers.length===12&&headers[0]==='KTV'&&headers.includes('WiFi 6 + 7 đã TH'))widths=[14,8,6.5,6.5,6.5,6.5,8,8,6.5,7,8,14.5];
 else if(headers.length===11&&headers[0]==='Đội trưởng')widths=[17,8,8,8,8,10,10,7,7,9,8];
 else if(headers.length===8&&headers.includes('PTTB đến 15/10'))widths=[10,13,9,11,11,12,13,21];
 const cols=widths.length?`<colgroup>${widths.map(w=>`<col style="width:${w}%">`).join('')}</colgroup>`:'';
 return `<div class="table-shell"><table class="data-table ${widths.length?'balanced-columns':''}">${cols}<thead><tr>${headers.map((x,i)=>`<th aria-sort="none"><button type="button" class="col-sort" data-col="${i}" aria-label="Sắp xếp cột ${esc(x)}" title="Nhấp để sắp xếp"><span class="sort-label">${x}</span><span class="sort-indicator" aria-hidden="true">↕</span></button></th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
};
const recallOriginalOpenModal=openModal;
openModal=function(title,sub,content){recallOriginalOpenModal(title,sub,content);let controls=$('detail-controls');if(!controls){controls=document.createElement('div');controls.id='detail-controls';controls.className='detail-controls';controls.innerHTML='<label for="detailSearch">Tìm trong bảng</label><input type="search" id="detailSearch" placeholder="Tên KTV, đội, mã HĐ hoặc nội dung…" autocomplete="off"><span id="detail-count"></span><span class="detail-sort-note">Bấm tiêu đề cột để sắp xếp</span>';$('modal-body').before(controls);$('detailSearch').addEventListener('input',refreshDetailSearch);}$('detailSearch').value='';enhanceDetails();};
function recallNormalize(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/\s+/g,' ').trim()}
function refreshDetailSearch(){
 const terms=recallNormalize($('detailSearch')?.value).split(' ').filter(Boolean);
 let total=0,shown=0;
 $('modal-body').querySelectorAll('.data-table tbody tr').forEach(row=>{total++;const text=recallNormalize(row.textContent);const matches=terms.every(t=>text.includes(t));row.hidden=!matches;if(matches)shown++;});
 const count=$('detail-count');if(count){const txt=`${nf(shown)} / ${nf(total)} dòng`;if(count.textContent!==txt)count.textContent=txt;}
 $('modal-body').classList.toggle('detail-empty',total>0&&shown===0);
}
applyColumnFilters=function(){refreshDetailSearch()};
function detailNumber(cell){
 const first=cell.querySelector('.v11-delta');
 let text=String(first?first.textContent:cell.textContent||'').trim().split('\n')[0].trim();
 if(!/^[-+]?\d+(?:[.,]\d+)*%?$/.test(text))return null;
 text=text.replace('%','');
 if(text.includes(','))text=text.replace(/\./g,'').replace(',','.');
 else if(/^[-+]?\d{1,3}(?:\.\d{3})+$/.test(text))text=text.replace(/\./g,'');
 const value=Number(text);return Number.isFinite(value)?value:null;
}
function detailTone(header){
 const h=recallNormalize(header).replace(/[^a-z0-9 ]/g,' ');
 if(h.includes('so cung ky'))return 'delta';
 if(h.includes('khong tc')||h.includes('khong thanh cong')||h.includes('csat')||h.includes('1 2')||h.includes('sao'))return 'red';
 if(h.includes('chua')||h.includes('cho nhap')||h.includes('ton'))return 'orange';
 if(h.includes('da th')||h.includes('da nhap')||h.includes('pttb')||h.includes('online')||h.includes('ty le')||h.includes('hoan thanh'))return 'green';
 return 'blue';
}
function applyDetailColors(){
 $('modal-body').querySelectorAll('.data-table').forEach(tbl=>{
  const rows=[...tbl.tBodies[0].rows];const headers=[...tbl.tHead.rows[0].cells];
  headers.forEach((header,index)=>{
   const values=rows.map(row=>detailNumber(row.cells[index]));
   const max=Math.max(0,...values.filter(v=>v!==null).map(Math.abs));
   const kind=detailTone(header.querySelector('.sort-label')?.dataset.fullLabel||header.querySelector('.col-sort')?.textContent||header.textContent);
   rows.forEach((row,i)=>{
    const cell=row.cells[index],value=values[i];if(value===null)return;
    const tone=kind==='delta'?(value<0?'red':'green'):kind;
    const attrs=recallToneAttrs(value,max,tone);
    const bg=attrs.match(/--value-bg:([^;]+)/)[1],ink=attrs.match(/--value-ink:([^"]+)/)[1];
    cell.classList.add('metric-tone');cell.style.setProperty('--value-bg',bg);cell.style.setProperty('--value-ink',ink);
   });
  });
 });
}
function enhanceDetails(){
 const body=$('modal-body');
 body.querySelectorAll('.modal-toolbar input,.modal-toolbar select').forEach(el=>el.remove());
 body.querySelectorAll('.modal-toolbar').forEach(el=>{if(!el.children.length)el.remove()});
 body.querySelectorAll('input.col-filter').forEach(el=>el.remove());
 body.querySelectorAll('.sales-note,.table-note').forEach(el=>{const old='; nhập ô ngay dưới để lọc từng cột.';if(el.textContent.includes(old))el.textContent=el.textContent.replace(old,'. Tìm nhanh bằng ô tìm kiếm phía trên.');});
 const hasTables=!!body.querySelector('.data-table');const controls=$('detail-controls');if(controls)controls.hidden=!hasTables;
 body.querySelectorAll('.data-table thead th').forEach(th=>{const button=th.querySelector('.col-sort');th.setAttribute('aria-sort',button?.classList.contains('asc')?'ascending':button?.classList.contains('desc')?'descending':'none');});
 applyDetailColors();refreshDetailSearch();
}
const recallDetailObserver=new MutationObserver(enhanceDetails);
recallDetailObserver.observe($('modal-body'),{childList:true,subtree:true});
document.addEventListener('click',e=>{if(e.target.closest('.col-sort'))enhanceDetails()});

let recallMode='all',recallTeam='Tất cả';
function openRecovery(mode='all',team='Tất cả'){
 recallMode=mode;recallTeam=team;
 openModal('THU HỒI THIẾT BỊ SG10',`${RECALL.period}, phân công theo ngày tạo. Đơn vị: thiết bị.`, '<div id="recovery-detail"></div>');
 renderRecovery();
}
function changeRecovery(mode){recallMode=mode;recallTeam='Tất cả';if($('detailSearch'))$('detailSearch').value='';renderRecovery()}
function renderRecovery(){
 const tabs=[['teams','5 đội'],['all',`${RECALL.staff.filter(p=>p.total>0&&p.account!=='CHUA_PC').length} KTV + Chưa PC`],['pending',`${RECALL.pendingCount} KTV còn tồn`],['zero',`${RECALL.zeroCount} KTV chưa có kết quả`],['risk','Không thành công cao'],['wifi','WiFi 6 + WiFi 7'],['warehouse','Chờ nhập kho']];
 let list=RECALL.staff.filter(p=>p.total>0&&(recallTeam==='Tất cả'||p.team===recallTeam));
 if(recallMode==='pending')list=list.filter(p=>p.account!=='CHUA_PC'&&p.pending>0).sort((a,b)=>b.pending-a.pending||a.name.localeCompare(b.name));
 else if(recallMode==='zero')list=list.filter(p=>p.account!=='CHUA_PC'&&p.total>0&&p.recovered===0).sort((a,b)=>b.pending-a.pending||b.total-a.total||a.name.localeCompare(b.name));
 else if(recallMode==='risk')list=list.filter(p=>p.account!=='CHUA_PC'&&p.total>0&&recallRatio(p.failed,p.total)>recallBase).sort((a,b)=>(b.total>=10)-(a.total>=10)||b.failed/b.total-a.failed/a.total||b.failed-a.failed);
 else if(recallMode==='wifi')list=list.filter(p=>p.wifiRecovered>0).sort((a,b)=>b.wifiRecovered-a.wifiRecovered||a.name.localeCompare(b.name));
 else if(recallMode==='warehouse')list=list.filter(p=>p.waiting>0).sort((a,b)=>b.waiting-a.waiting||a.name.localeCompare(b.name));
 else if(recallMode==='recovered')list=list.filter(p=>p.recovered>0).sort((a,b)=>b.recovered-a.recovered||a.name.localeCompare(b.name));
 else if(recallMode==='failed')list=list.filter(p=>p.failed>0).sort((a,b)=>b.failed-a.failed||a.name.localeCompare(b.name));
 else list.sort((a,b)=>a.team.localeCompare(b.team)||b.pending-a.pending||a.name.localeCompare(b.name));
 let description=recallTeam!=='Tất cả'?`Đội ${recallTeam}. `:'';
 if(recallMode==='zero')description+='Có phân công và số thiết bị đã TH = 0. Bao gồm trường hợp chỉ có thu hồi không thành công.';
 else if(recallMode==='risk')description+=`Không TC / tổng phân công cao hơn mức chung SG10 ${recallPct(recallBase)}. Mẫu từ 10 thiết bị xếp trước, mẫu nhỏ ghi chú riêng.`;
 else if(recallMode==='wifi')description+=`WiFi 6 + WiFi 7: số lượng đã TH và tỷ lệ lấy từ cột AB–AC của tab Báo Cáo Thu Hồi. Tổng: ${RECALL.summary.wifiRecovered} thiết bị, ${RECALL.summary.wifiRate}.`;
 else if(recallMode==='warehouse')description+=`Đã thu hồi nhưng chưa nhập kho. Tổng SG10 còn ${RECALL.summary.waiting} thiết bị.`;
 else description+='Tỷ lệ đã TH và không TC đều dùng tổng phân công của từng nhân sự làm mẫu số.';
 let content='';
 if(recallMode==='teams'){
  const groups=[...RECALL.teams].sort((a,b)=>b.recovered/b.total-a.recovered/a.total);
  content=table(['Đội trưởng','Phân công','Chưa TH','Không TC','Đã TH','Tỷ lệ đã TH','Tỷ lệ không TC','Đã nhập kho','Chờ nhập kho','WiFi 6 + 7 đã TH','Tỷ lệ WiFi 6 + 7'],groups.map(t=>`<tr class="row-${cls(t.team)}"><td>${badge(t.team)}<span class="recall-leader">${esc(t.leader)}</span></td><td class="num">${t.total}</td><td class="num">${t.pending}</td><td class="num">${t.failed}</td><td class="num strong ok">${t.recovered}</td><td class="num ok">${recallPct(recallRatio(t.recovered,t.total))}</td><td class="num danger">${recallPct(recallRatio(t.failed,t.total))}</td><td class="num">${t.warehouse}</td><td class="num">${t.waiting}</td><td class="num ok">${t.wifiRecovered}</td><td class="num">${t.wifiRate||'—'}</td></tr>`));
 } else {
  const row=p=>`<tr class="row-${cls(p.team)}"><td><b>${esc(p.name)}</b><span class="recall-account">${esc(p.account)}</span></td><td>${badge(p.team)}</td><td class="num">${p.total}</td><td class="num ${p.pending?'recall-orange':''}">${p.pending}</td><td class="num">${p.failed}</td><td class="num ${p.recovered?'ok':'danger'}">${p.recovered}</td><td class="num">${recallPct(recallRatio(p.recovered,p.total))}</td><td class="num ${recallRatio(p.failed,p.total)>recallBase?'danger':''}">${recallPct(recallRatio(p.failed,p.total))}</td><td class="num">${p.waiting}</td><td class="num ok">${p.wifiRecovered}</td><td class="num">${p.wifiRate||'—'}</td><td class="recall-row-note">${p.total<10?'Mẫu nhỏ: '+p.total+' TB':p.recovered===0?'Chưa có kết quả TH':p.waiting>0?'Còn chờ nhập kho':'Có kết quả TH'}</td></tr>`;
  content=table(['KTV','Đội','Phân công','Chưa TH','Không TC','Đã TH','Tỷ lệ đã TH','Tỷ lệ không TC','Chờ nhập kho','WiFi 6 + 7 đã TH','Tỷ lệ WiFi 6 + 7','Ghi chú'],list.map(row));
 }
 $('recovery-detail').innerHTML=toolbar(tabs,recallMode,'changeRecovery')+`<p class="recall-sync-note"><strong>● DỮ LIỆU CHỐT ${RECALL.snapshot}</strong> · Slide chưa đồng bộ trực tiếp với Google Sheet. Các chỉ số này không tự thay đổi khi Data_TH cập nhật.</p><p class="detail-description">${description}</p><div class="recovery-detail-board">${content}</div><p class="table-note">Màu ô: đã TH xanh, chưa TH/chờ nhập kho cam, không TC đỏ, số 0 nền trắng. Độ đậm tăng theo giá trị trong cùng cột. Nguồn: ${RECALL.source}. Tổng SG10 ${nf(RECALL.summary.total)} = ${nf(RECALL.summary.pending)} chưa TH + ${nf(RECALL.summary.failed)} không TC + ${nf(RECALL.summary.recovered)} đã TH. Đã TH = ${nf(RECALL.summary.warehouse)} nhập kho + ${nf(RECALL.summary.waiting)} chưa nhập kho. WiFi 6 + 7 đã TH: ${RECALL.summary.wifiRecovered}; tỷ lệ ${RECALL.summary.wifiRate} theo cột AB–AC. Phạm vi ${RECALL.scope}.</p>`;
 enhanceDetails();
}
window.__PKT.openRecovery=openRecovery;
